import React, { useState, useEffect, useCallback } from 'react';
import { Flow } from 'flow-sdk';
import { motion, AnimatePresence } from 'motion/react';
import JSZip from 'jszip';
import { BrandPanel } from './components/BrandPanel';
import { SlidePlanner } from './components/SlidePlanner';
import { CarouselPreview } from './components/CarouselPreview';
import { BrandIdentity, SlideData } from './types';
import { generateSlide } from './services/generator';

const INITIAL_BRAND: BrandIdentity = {
  companyName: 'My Brand',
  primaryColor: '#3b82f6', // Standard blue
  secondaryColor: '#ffffff',
  accentColor: '#1e293b', // Slate navy
  fontFamily: 'Modern Sans',
  tone: 'Professional',
  aspectRatio: '1:1'
};

const INITIAL_SLIDES: SlideData[] = [
  { 
    id: '1', 
    type: 'cover', 
    instruction: 'Modern clean mockup design with bold typography', 
    content: 'The Future of Our Industry',
    status: 'idle' 
  },
  { 
    id: '2', 
    type: 'content', 
    instruction: 'Strategy Insight: Clean data visuals and infographics', 
    content: 'Key Growth Drivers for the Next Year',
    status: 'idle' 
  },
  { 
    id: '3', 
    type: 'content', 
    instruction: 'Execution Plan: Multichannel layout', 
    content: 'Our Strategic Roadmap to Success',
    status: 'idle' 
  },
  { 
    id: '4', 
    type: 'content', 
    instruction: 'Result Metrics: High contrast data points', 
    content: 'Significant ROI for our partners',
    status: 'idle' 
  },
  { 
    id: '5', 
    type: 'outro', 
    instruction: 'Clean professional footer with call to action', 
    content: 'Let\'s collaborate: contact@brand.com',
    status: 'idle' 
  },
];

export default function App() {
  const [brand, setBrand] = useState<BrandIdentity>(INITIAL_BRAND);
  const [slides, setSlides] = useState<SlideData[]>(INITIAL_SLIDES);
  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const id = 'brand-design-system';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #333; border-radius: 10px; }
      @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
      .animate-shimmer { background: linear-gradient(90deg, #1a1a1a 25%, #2a2a2a 50%, #1a1a1a 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
      html, body, #root { height: 100%; background: #0e0e0e; color: white; font-family: 'Google Sans Text', sans-serif; overflow: hidden; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleGenerateSlide = async (slideId: string) => {
    const slideIndex = slides.findIndex(s => s.id === slideId);
    if (slideIndex === -1 || isGenerating) return;

    setError(null);
    const updatedSlides = [...slides];
    updatedSlides[slideIndex] = { ...updatedSlides[slideIndex], status: 'generating' };
    setSlides(updatedSlides);

    try {
      const result = await generateSlide(updatedSlides[slideIndex], brand);
      setSlides(prev => prev.map(s => s.id === slideId ? { 
        ...s, 
        status: 'completed', 
        resultMedia: result 
      } : s));
    } catch (err: any) {
      setSlides(prev => prev.map(s => s.id === slideId ? { ...s, status: 'error' } : s));
      setError(`Slide ${slideIndex + 1} failed: ${err.message}`);
    }
  };

  const handleGenerateAll = async () => {
    if (isGenerating) return;
    setIsGenerating(true);
    setError(null);
    setProgress(0);

    const updatedSlides = [...slides];

    try {
      for (let i = 0; i < slides.length; i++) {
        updatedSlides[i] = { ...updatedSlides[i], status: 'generating' };
        setSlides([...updatedSlides]);

        try {
          const result = await generateSlide(updatedSlides[i], brand);
          updatedSlides[i] = { 
            ...updatedSlides[i], 
            status: 'completed', 
            resultMedia: result 
          };
        } catch (err: any) {
          updatedSlides[i] = { ...updatedSlides[i], status: 'error' };
          setError(`Slide ${i + 1} failed: ${err.message}`);
        }

        setSlides([...updatedSlides]);
        setProgress(((i + 1) / slides.length) * 100);
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownload = async () => {
    const completedSlides = slides.filter(s => s && s.status === 'completed' && s.resultMedia);
    if (completedSlides.length === 0) return;

    const zip = new JSZip();
    completedSlides.forEach((slide, index) => {
      if (slide.resultMedia) {
        zip.file(`slide_${index + 1}.jpg`, slide.resultMedia.base64, { base64: true });
      }
    });

    try {
      const content = await zip.generateAsync({ type: 'blob' });
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = (reader.result as string).split(',')[1];
        await Flow.download({
          base64,
          mimeType: 'application/zip',
          filename: `${brand.companyName.toLowerCase().replace(/\s+/g, '_')}_carousel.zip`
        });
      };
      reader.readAsDataURL(content);
    } catch (err) {
      setError('Export failed. Please try again.');
    }
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#0e0e0e]">
      {/* Left Config Panel */}
      <div className="w-[320px] h-full border-r border-white/10 flex flex-col bg-[#0a0a0a] z-10 shrink-0">
        <div className="p-4 border-b border-white/10 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="material-symbols-outlined text-blue-500">design_services</span>
            <h1 className="font-bold text-[13px] uppercase tracking-widest text-white/90">Carousel Designer</h1>
          </div>
          <div className="px-2 py-0.5 rounded-full bg-blue-500/10 border border-blue-500/20 text-[9px] font-bold text-blue-400">PRO</div>
        </div>

        <div className="flex-1 overflow-y-auto dark-scrollbar">
          <BrandPanel brand={brand} setBrand={setBrand} />
          <SlidePlanner 
            slides={slides} 
            setSlides={setSlides} 
            isGenerating={isGenerating} 
            onGenerateSingle={handleGenerateSlide}
          />
        </div>

        <div className="p-4 border-t border-white/10 flex flex-col gap-2 bg-[#0d0d0d]">
          <button
            onClick={handleGenerateAll}
            disabled={isGenerating}
            className={`w-full h-11 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
              isGenerating ? 'bg-white/10 text-white/40 cursor-not-allowed' : 'bg-white text-black hover:bg-gray-200'
            }`}
          >
            {isGenerating ? (
              <>
                <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin" />
                Crafting... {Math.round(progress)}%
              </>
            ) : (
              <>
                <span className="material-symbols-outlined text-[20px]">magic_button</span>
                Build Carousel
              </>
            )}
          </button>

          <button
            onClick={handleDownload}
            disabled={isGenerating || !slides.some(s => s && s.status === 'completed')}
            className="w-full h-11 rounded-xl border border-white/10 font-medium flex items-center justify-center gap-2 hover:bg-white/5 transition-all disabled:opacity-30 text-[12px]"
          >
            <span className="material-symbols-outlined text-[18px]">file_download</span>
            Export for LinkedIn
          </button>
        </div>
      </div>

      {/* Main Preview Area */}
      <div className="flex-1 h-full bg-[#050505] relative overflow-hidden flex flex-col">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_#111_0%,_#050505_100%)]" />

        {/* Top Branding Bar */}
        <div className="relative z-10 px-8 py-4 flex justify-between items-center bg-black/20 backdrop-blur-sm border-b border-white/5">
          <div className="flex flex-col">
            <span className="text-[10px] font-bold text-white/30 uppercase tracking-widest">Active Project</span>
            <span className="text-xs font-medium text-white/80">{brand.companyName} Campaign</span>
          </div>
          <div className="flex items-center gap-4">
             <div className="flex -space-x-2">
                {[1,2,3].map(i => (
                  <div key={i} className="w-6 h-6 rounded-full border-2 border-[#050505] bg-gradient-to-br from-blue-500 to-indigo-600" />
                ))}
             </div>
             <span className="text-[10px] text-white/40 font-medium tracking-wide">Live Preview Mode</span>
          </div>
        </div>

        <div className="relative flex-1 flex items-center justify-center p-12">
          <CarouselPreview 
            slides={slides} 
            isGenerating={isGenerating} 
            onRegenerate={handleGenerateSlide} 
            aspectRatio={brand.aspectRatio}
          />
        </div>

        {error && (
          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-red-500/90 backdrop-blur-md px-4 py-2 rounded-full text-xs font-medium flex items-center gap-2 border border-red-400/50 shadow-2xl">
            <span className="material-symbols-outlined text-sm">warning</span>
            {error}
            <button onClick={() => setError(null)} className="ml-2 hover:opacity-70">
              <span className="material-symbols-outlined text-sm">close</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import { MediaItem } from 'flow-sdk';

export type AspectRatio = '1:1' | '16:9' | '9:16' | '4:3' | '3:4';

export interface BrandIdentity {
  companyName: string;
  primaryColor: string;
  secondaryColor: string;
  accentColor: string;
  fontFamily: string;
  tone: string;
  aspectRatio: AspectRatio;
  logo?: MediaItem;
}

export type SlideType = 'cover' | 'content' | 'outro';
export type SlideStatus = 'idle' | 'generating' | 'completed' | 'error';
export type InfluenceMode = 'style' | 'structure' | 'strict';

export interface SlideData {
  id: string;
  type: SlideType;
  instruction: string; // The "how" - design direction
  content: string;     // The "what" - actual text/info
  inspirationMedia?: MediaItem;
  influenceMode?: InfluenceMode;
  status: SlideStatus;
  resultMedia?: {
    base64: string;
    mimeType: string;
    mediaId: string;
  };
}

import React, { useState, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { BrandIdentity, AspectRatio } from '../types';

interface BrandPanelProps {
  brand: BrandIdentity;
  setBrand: React.Dispatch<React.SetStateAction<BrandIdentity>>;
}

export const BrandPanel: React.FC<BrandPanelProps> = ({ brand, setBrand }) => {
  const update = (key: keyof BrandIdentity, val: any) => setBrand(prev => ({ ...prev, [key]: val }));

  const handleUploadLogo = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      update('logo', media);
    } catch (err) {
      console.error('Failed to select logo:', err);
    }
  };

  return (
    <div className="p-4 flex flex-col gap-6">
      <div>
        <label className="text-[10px] font-bold text-white/30 uppercase tracking-widest block mb-3">Identity</label>
        <div className="flex flex-col gap-1.5">
          <label className="text-[9px] text-white/40 font-medium uppercase tracking-tighter">Company Name</label>
          <input 
            type="text"
            value={brand.companyName}
            onChange={e => update('companyName', e.target.value)}
            placeholder="Enter brand name..."
            className="w-full bg-[#1a1a1a] border border-white/10 rounded-lg h-10 px-3 text-xs text-white focus:outline-none focus:border-blue-500/50"
          />
        </div>
      </div>

      <div>
        <label className="text-[10px] font-bold text-white/30 uppercase tracking-widest block mb-3">Brand Palette</label>
        <div className="flex flex-col gap-3">
          <ColorInput label="Primary Color" value={brand.primaryColor} onChange={v => update('primaryColor', v)} />
          <ColorInput label="Secondary Color" value={brand.secondaryColor} onChange={v => update('secondaryColor', v)} />
          <ColorInput label="Accent Color" value={brand.accentColor} onChange={v => update('accentColor', v)} />
        </div>
      </div>

      <div>
        <label className="text-[10px] font-bold text-white/30 uppercase tracking-widest block mb-3">Slide Format</label>
        <div className="grid grid-cols-5 gap-1">
          {(['1:1', '16:9', '9:16', '4:3', '3:4'] as AspectRatio[]).map((ratio) => (
            <button
              key={ratio}
              onClick={() => update('aspectRatio', ratio)}
              className={`flex flex-col items-center justify-center p-1.5 rounded-lg border transition-all ${
                brand.aspectRatio === ratio 
                  ? 'bg-blue-500/20 border-blue-500/50 text-blue-400' 
                  : 'bg-white/5 border-white/5 text-white/40 hover:bg-white/10'
              }`}
            >
              <div className={`mb-1 border-current border ${
                ratio === '1:1' ? 'w-3 h-3' : 
                ratio === '16:9' ? 'w-4 h-2.5' :
                ratio === '9:16' ? 'w-2 h-4' :
                ratio === '4:3' ? 'w-4 h-3' : 'w-3 h-4'
              }`} />
              <span className="text-[8px] font-bold">{ratio}</span>
            </button>
          ))}
        </div>
      </div>

      <div className="flex flex-col gap-3">
        <label className="text-[10px] font-bold text-white/30 uppercase tracking-widest block">Consistency Assets</label>

        {brand.logo ? (
          <div className="relative group rounded-xl overflow-hidden aspect-[4/1] bg-white/5 border border-white/10 flex items-center justify-center p-2">
            <img 
              src={`data:${brand.logo.mimeType};base64,${brand.logo.base64}`} 
              className="max-h-full max-w-full object-contain"
              alt="Brand Logo"
            />
            <button 
              onClick={() => update('logo', undefined)}
              className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center gap-2 transition-opacity text-[10px] font-bold"
            >
              <span className="material-symbols-outlined text-sm">delete</span>
              REMOVE LOGO
            </button>
          </div>
        ) : (
          <button
            onClick={handleUploadLogo}
            className="w-full h-12 rounded-xl bg-white/5 border border-dashed border-white/10 flex flex-col items-center justify-center gap-1 text-[10px] text-white/40 hover:bg-white/10 hover:text-white/60 transition-all"
          >
            <span className="material-symbols-outlined text-[18px]">identity_platform</span>
            <span>Upload Brand Logo</span>
          </button>
        )}
      </div>

      <div className="grid grid-cols-2 gap-2">
        <div className="flex flex-col gap-1.5">
          <label className="text-[10px] text-white/40 font-medium">Font Vibe</label>
          <select 
            value={brand.fontFamily}
            onChange={e => update('fontFamily', e.target.value)}
            className="bg-[#1a1a1a] border border-white/10 rounded-lg h-9 px-2 text-xs focus:outline-none focus:border-blue-500/50"
          >
            <option>Modern Sans</option>
            <option>Classic Serif</option>
            <option>Minimalist</option>
            <option>Bold Impact</option>
          </select>
        </div>
        <div className="flex flex-col gap-1.5">
          <label className="text-[10px] text-white/40 font-medium">Tone</label>
          <select 
            value={brand.tone}
            onChange={e => update('tone', e.target.value)}
            className="bg-[#1a1a1a] border border-white/10 rounded-lg h-9 px-2 text-xs focus:outline-none focus:border-blue-500/50"
          >
            <option>Professional</option>
            <option>Energetic</option>
            <option>Minimal</option>
            <option>Futuristic</option>
          </select>
        </div>
      </div>
    </div>
  );
};

const ColorInput: React.FC<{ label: string; value: string; onChange: (v: string) => void }> = ({ label, value, onChange }) => {
  const [inputValue, setInputValue] = useState(value);

  useEffect(() => {
    setInputValue(value);
  }, [value]);

  const handleHexChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setInputValue(val);
    if (/^#[0-9A-F]{6}$/i.test(val)) {
      onChange(val);
    }
  };

  return (
    <div className="flex flex-col gap-1">
      <div className="flex items-center gap-2 h-10 w-full">
        <div className="relative w-10 h-10 shrink-0">
          <input 
            type="color" 
            value={value} 
            onChange={e => onChange(e.target.value)}
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
          />
          <div 
            className="w-full h-full rounded-lg border border-white/10 transition-transform hover:scale-105 shadow-lg" 
            style={{ backgroundColor: value }}
          />
        </div>
        <input 
          type="text"
          value={inputValue}
          onChange={handleHexChange}
          className="flex-1 min-w-0 bg-[#141414] border border-white/10 rounded-lg h-full px-3 text-[11px] font-mono text-white/90 focus:outline-none focus:border-blue-500/50 uppercase tracking-widest"
          placeholder="#000000"
        />
      </div>
      <span className="text-[9px] text-white/30 font-bold uppercase tracking-tighter pl-1">{label}</span>
    </div>
  );
};

import React from 'react';
import { Flow } from 'flow-sdk';
import { SlideData, InfluenceMode } from '../types';

interface SlidePlannerProps {
  slides: SlideData[];
  setSlides: React.Dispatch<React.SetStateAction<SlideData[]>>;
  isGenerating: boolean;
  onGenerateSingle: (id: string) => void;
}

export const SlidePlanner: React.FC<SlidePlannerProps> = ({ slides, setSlides, isGenerating, onGenerateSingle }) => {
  const updateSlide = (id: string, updates: Partial<SlideData>) => {
    setSlides(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleUploadInspiration = async (id: string) => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      updateSlide(id, { inspirationMedia: media, influenceMode: 'structure' });
    } catch (err) {
      console.error('Failed to select media:', err);
    }
  };

  const removeInspirationMedia = (id: string) => {
    updateSlide(id, { inspirationMedia: undefined, influenceMode: undefined });
  };

  const addSlide = () => {
    if (slides.length >= 10) return;
    const newSlide: SlideData = {
      id: Math.random().toString(36).substr(2, 9),
      type: 'content',
      instruction: 'Continue the design style...',
      content: 'Add your key message here',
      status: 'idle'
    };

    // Insert the new slide before the CTA (the last slide)
    setSlides(prev => {
      const next = [...prev];
      const insertIndex = Math.max(0, next.length - 1);
      next.splice(insertIndex, 0, newSlide);
      return next;
    });
  };

  const removeSlide = (id: string) => {
    // Keep at least the Cover, one Content page, and the Outro
    if (slides.length <= 3) return;
    setSlides(prev => prev.filter(s => s.id !== id));
  };

  return (
    <div className="p-4 flex flex-col gap-4">
      <div className="flex items-center justify-between">
        <label className="text-[10px] font-bold text-white/30 uppercase tracking-widest">Carousel Flow</label>
        <span className="text-[10px] text-white/20">{slides.length}/10</span>
      </div>

      <div className="flex flex-col gap-3">
        {slides.map((slide, index) => (
          <div key={slide.id} className={`group relative p-3 rounded-xl border transition-all ${
            slide.status === 'generating' ? 'border-blue-500/50 bg-blue-500/5' : 'border-white/5 bg-[#141414]'
          }`}>
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                <div className={`w-5 h-5 rounded-md flex items-center justify-center text-[10px] font-bold ${
                  slide.type === 'cover' ? 'bg-blue-500 text-white' : 
                  slide.type === 'outro' ? 'bg-purple-500 text-white' : 'bg-white/10 text-white/60'
                }`}>
                  {index + 1}
                </div>
                <span className="text-[10px] font-medium text-white/60 uppercase tracking-wide">
                  {slide.type === 'cover' ? 'Opening Cover' : slide.type === 'outro' ? 'Call to Action' : 'Content Page'}
                </span>
              </div>
              <div className="flex items-center gap-1.5">
                {slide.status === 'completed' && !isGenerating && (
                  <button 
                    onClick={() => onGenerateSingle(slide.id)}
                    title="Regenerate this slide"
                    className="p-1 rounded-md bg-white/5 hover:bg-blue-500/20 text-white/40 hover:text-blue-400 transition-all"
                  >
                    <span className="material-symbols-outlined text-[16px]">refresh</span>
                  </button>
                )}
                {/* Continuity pages (content type) are always deletable */}
                {!isGenerating && slide.type === 'content' && (
                  <button 
                    onClick={() => removeSlide(slide.id)}
                    className="opacity-0 group-hover:opacity-100 transition-opacity text-white/30 hover:text-red-400"
                  >
                    <span className="material-symbols-outlined text-[16px]">delete</span>
                  </button>
                )}
              </div>
            </div>

            <div className="flex flex-col gap-2">
              <div className="flex flex-col gap-1">
                <label className="text-[9px] font-bold text-white/20 uppercase tracking-tighter">Instructions</label>
                <textarea
                  value={slide.instruction}
                  onChange={(e) => updateSlide(slide.id, { instruction: e.target.value })}
                  disabled={isGenerating}
                  placeholder="Design direction (e.g. 'minimalist mockup')..."
                  className="w-full bg-black/20 rounded-lg p-2 text-[11px] text-white/80 resize-none h-12 border border-white/5 focus:border-white/10 focus:outline-none transition-colors dark-scrollbar"
                />
              </div>

              <div className="flex flex-col gap-1">
                <label className="text-[9px] font-bold text-white/20 uppercase tracking-tighter">Content</label>
                <textarea
                  value={slide.content}
                  onChange={(e) => updateSlide(slide.id, { content: e.target.value })}
                  disabled={isGenerating}
                  placeholder="Text to display on slide..."
                  className="w-full bg-black/20 rounded-lg p-2 text-[11px] text-white/80 resize-none h-12 border border-white/5 focus:border-white/10 focus:outline-none transition-colors dark-scrollbar"
                />
              </div>

              {slide.inspirationMedia ? (
                <div className="flex flex-col gap-2 mt-1">
                  <div className="relative w-full aspect-video rounded-lg overflow-hidden border border-white/10 bg-black/40 group/media">
                    <img 
                      src={`data:${slide.inspirationMedia.mimeType};base64,${slide.inspirationMedia.base64}`} 
                      className="w-full h-full object-cover opacity-60 group-hover/media:opacity-100 transition-opacity"
                      alt="Inspiration"
                    />
                    {!isGenerating && (
                      <button 
                        onClick={() => removeInspirationMedia(slide.id)}
                        className="absolute top-1 right-1 w-6 h-6 bg-black/60 backdrop-blur-md rounded-full flex items-center justify-center text-white/80 hover:text-red-400 transition-colors"
                      >
                        <span className="material-symbols-outlined text-[14px]">close</span>
                      </button>
                    )}
                  </div>

                  {/* Similarity Mode Selector */}
                  <div className="flex items-center gap-1 bg-black/40 p-1 rounded-lg border border-white/5">
                    {(['style', 'structure', 'strict'] as InfluenceMode[]).map((mode) => (
                      <button
                        key={mode}
                        disabled={isGenerating}
                        onClick={() => updateSlide(slide.id, { influenceMode: mode })}
                        className={`flex-1 py-1 rounded-md text-[8px] font-bold uppercase tracking-tighter transition-all ${
                          slide.influenceMode === mode 
                            ? 'bg-blue-500 text-white' 
                            : 'text-white/30 hover:text-white/60 hover:bg-white/5'
                        }`}
                      >
                        {mode}
                      </button>
                    ))}
                  </div>
                </div>
              ) : (
                <button
                  onClick={() => handleUploadInspiration(slide.id)}
                  disabled={isGenerating}
                  className="w-full h-8 rounded-lg bg-white/5 border border-dashed border-white/10 flex items-center justify-center gap-2 text-[10px] text-white/40 hover:bg-white/10 hover:text-white/60 transition-all"
                >
                  <span className="material-symbols-outlined text-[14px]">add_photo_alternate</span>
                  Add Mockup/Inspiration
                </button>
              )}
            </div>

            {slide.status === 'generating' && (
              <div className="absolute inset-0 bg-blue-500/5 rounded-xl animate-pulse pointer-events-none" />
            )}
          </div>
        ))}

        {!isGenerating && slides.length < 10 && (
          <button 
            onClick={addSlide}
            className="h-10 border border-dashed border-white/10 rounded-xl flex items-center justify-center gap-2 text-white/40 hover:text-white/60 hover:border-white/20 transition-all text-xs"
          >
            <span className="material-symbols-outlined text-sm">add</span>
            Add Continuity Page
          </button>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { SlideData, AspectRatio } from '../types';

interface CarouselPreviewProps {
  slides: SlideData[];
  isGenerating: boolean;
  onRegenerate: (id: string) => void;
  aspectRatio: AspectRatio;
}

export const CarouselPreview: React.FC<CarouselPreviewProps> = ({ slides, isGenerating, onRegenerate, aspectRatio }) => {
  const [currentIndex, setCurrentIndex] = useState(0);

  // Sync index if slides are removed
  useEffect(() => {
    if (currentIndex >= slides.length) {
      setCurrentIndex(Math.max(0, slides.length - 1));
    }
  }, [slides.length, currentIndex]);

  const next = () => setCurrentIndex(prev => (prev + 1) % slides.length);
  const prev = () => setCurrentIndex(prev => (prev - 1 + slides.length) % slides.length);

  const activeSlide = slides[currentIndex];

  if (!activeSlide) {
    return (
      <div 
        className="w-full max-w-[450px] relative flex items-center justify-center bg-[#0a0a0a] rounded-[2rem] border border-white/5"
        style={{ aspectRatio: aspectRatio.replace(':', '/') }}
      >
        <span className="text-white/20 text-xs uppercase tracking-widest font-bold">No slides available</span>
      </div>
    );
  }

  return (
    <div 
      className="w-full max-w-[450px] relative transition-all duration-500 ease-in-out"
      style={{ aspectRatio: aspectRatio.replace(':', '/') }}
    >
      <div className="absolute inset-0 bg-black rounded-[2rem] shadow-[0_40px_100px_rgba(0,0,0,0.8)] overflow-hidden border border-white/5">
        <AnimatePresence mode="wait">
          <motion.div
            key={`${currentIndex}-${aspectRatio}`}
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.05 }}
            className="w-full h-full relative group"
          >
            {activeSlide.status === 'completed' && activeSlide.resultMedia ? (
              <>
                <img 
                  src={`data:${activeSlide.resultMedia.mimeType};base64,${activeSlide.resultMedia.base64}`} 
                  className="w-full h-full object-cover"
                  alt={`Slide ${currentIndex + 1}`}
                />
                {!isGenerating && (
                  <button 
                    onClick={() => onRegenerate(activeSlide.id)}
                    className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-black/60 backdrop-blur-md border border-white/20 px-4 py-2 rounded-full text-xs font-bold text-white opacity-0 group-hover:opacity-100 transition-all flex items-center gap-2 hover:bg-blue-500 hover:border-blue-400"
                  >
                    <span className="material-symbols-outlined text-sm">refresh</span>
                    RE-ATTEMPT SLIDE
                  </button>
                )}
              </>
            ) : (
              <div className="w-full h-full flex flex-col items-center justify-center p-8 bg-[#0a0a0a]">
                <div className={`w-20 h-20 rounded-2xl flex items-center justify-center mb-4 ${
                  activeSlide.status === 'generating' ? 'animate-pulse bg-blue-500/20 text-blue-400' : 'bg-white/5 text-white/20'
                }`}>
                  <span className="material-symbols-outlined text-[40px]">
                    {activeSlide.status === 'generating' ? 'auto_awesome' : 'image'}
                  </span>
                </div>
                <h3 className="text-sm font-bold text-white/40 text-center">
                  {activeSlide.status === 'generating' ? 'AI is crafting this slide...' : 'Slide Not Generated'}
                </h3>
                <p className="text-[10px] text-white/20 text-center mt-2 max-w-[200px]">
                  {activeSlide.status === 'generating' ? 'Applying brand palette and typography...' : 'Configure inspiration and hit generate.'}
                </p>
              </div>
            )}
          </motion.div>
        </AnimatePresence>

        {/* Navigation Overlays */}
        {slides.length > 0 && (
          <div className="absolute inset-x-0 bottom-8 flex items-center justify-center gap-4 z-20">
            <button 
              onClick={prev}
              className="w-10 h-10 rounded-full bg-black/40 backdrop-blur-md border border-white/10 flex items-center justify-center hover:bg-white/10 transition-colors"
            >
              <span className="material-symbols-outlined text-sm">chevron_left</span>
            </button>

            <div className="flex gap-1.5 px-3 py-1.5 bg-black/40 backdrop-blur-md rounded-full border border-white/5">
              {slides.map((_, i) => (
                <div 
                  key={i} 
                  className={`w-1 h-1 rounded-full transition-all ${i === currentIndex ? 'bg-blue-400 w-3' : 'bg-white/20'}`}
                />
              ))}
            </div>

            <button 
              onClick={next}
              className="w-10 h-10 rounded-full bg-black/40 backdrop-blur-md border border-white/10 flex items-center justify-center hover:bg-white/10 transition-colors"
            >
              <span className="material-symbols-outlined text-sm">chevron_right</span>
            </button>
          </div>
        )}

        <div className="absolute top-6 left-6 z-20 pointer-events-none">
          <div className="px-2 py-1 bg-black/40 backdrop-blur-md rounded-md border border-white/10 text-[10px] font-bold text-white/60 tracking-tighter uppercase">
            Page {currentIndex + 1} / {slides.length}
          </div>
        </div>
      </div>

      {/* Decorative shadows */}
      <div className="absolute -inset-4 bg-blue-500/5 blur-[100px] -z-10" />
    </div>
  );
};

import { Flow } from 'flow-sdk';
import { SlideData, BrandIdentity } from '../types';

export async function generateSlide(slide: SlideData, brand: BrandIdentity) {
  const isStrict = slide.influenceMode === 'strict';
  const isStructure = slide.influenceMode === 'structure';

  const prompt = `
    ACT AS A SENIOR BRAND DESIGNER.
    ${slide.inspirationMedia ? `
      REIMAGINE THE ATTACHED REFERENCE AS A HIGH-END MOCKUP.
      ${isStrict ? 'MANDATORY: Maintain the exact layout, composition, and core visual elements of the reference image.' : ''}
      ${isStructure ? 'CORE TASK: Use the layout and structural arrangement of the reference image as the foundation.' : ''}
    ` : 'CREATE A NEW high-fidelity marketing slide mockup.'}

    ${brand.logo ? 'INTEGRATE THE PROVIDED LOGO: Place the attached company logo professionally within the composition. CRITICAL: Maintain the logo\'s original colors, branding, and proportions exactly. Do not invert or stylize the logo colors.' : ''}

    SLIDE TYPE: ${slide.type.toUpperCase()}
    INSTRUCTION: "${slide.instruction}"
    CONTENT: "${slide.content}"

    BRAND IDENTITY:
    - Company Name: ${brand.companyName}
    - Primary Color: ${brand.primaryColor}
    - Secondary/Background: ${brand.secondaryColor}
    - Accent: ${brand.accentColor}
    - Tone: ${brand.tone} (Corporate high-fidelity)
    - Typography Style: ${brand.fontFamily}

    TECHNICAL REQUIREMENTS:
    - Aspect ratio: ${brand.aspectRatio}.
    - VISUAL BREATHING AREA: Maintain a clear 20px "safe zone" margin around all edges of the slide. No text or critical content should touch the edges.
    - Professional agency aesthetic.
    - High contrast, sharp text rendering.
    - Minimalist, premium vibe.
  `.trim();

  // Combine inspiration and logo for multi-reference generation
  const referenceImageMediaIds: string[] = [];
  if (slide.inspirationMedia) referenceImageMediaIds.push(slide.inspirationMedia.mediaId);
  if (brand.logo) referenceImageMediaIds.push(brand.logo.mediaId);

  const result = await Flow.generate.image({
    prompt,
    modelDisplayName: '🍌 Nano Banana Pro',
    aspectRatio: brand.aspectRatio,
    referenceImageMediaIds: referenceImageMediaIds.length > 0 ? referenceImageMediaIds : undefined,
  });

  return result;
}
